mapper.select:
select '流程中' as workStatus , wft.TOTLE_TRADE_ID as tradeId, wft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, wft.PORTFOLIO_ID as prodId, wft.TRADE_AMT as tradeAmt, null as portfolioId, null as portfolioName, null as allotAmt, wft.WORKFLOW_ID as workflowId, '02' hasChildren, CONCAT('流程中',nvl(wft.PORTFOLIO_ID,'null')) childInfo, 'root' parentInfo, wft.ccy as ccy,
ptp.PORTFOLIO_ID AS portfolioId1
from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where 1=1
and wft.BUSI_TYPE=#{busiType}
and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= to_date(#{vdateStart},'yyyy-mm-dd')
and wft.SETTLE_DATE <= to_date(#{vdateEnd},'yyyy-mm-dd')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} group by wft.TOTLE_TRADE_ID,wft.SETTLE_DATE,fp.FINPROD_NAME,
wft.PORTFOLIO_ID,wft.TRADE_AMt,wft.WORKFLOW_ID,wft.ccy,ptp.PORTFOLIO_ID
union all
select null as workStatus , null as tradeId, null as settleDate, null as prodName, null as prodId, null as tradeAmt, wta.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, decode(wpt.ps,#{ps},-1*wpt.TRADE_AMT,wpt.TRADE_AMT) as allotAmt, null as workflowId, '01' hasChildren, CONCAT(CONCAT('流程中',nvl(wft.PORTFOLIO_ID,'null')),wft.TOTLE_TRADE_ID) childInfo, CONCAT('流程中',nvl(wft.PORTFOLIO_ID,'null')) parentInfo, null as ccy,
ptp.PORTFOLIO_ID AS portfolioId1
from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where 1=1
and wft.BUSI_TYPE=#{busiType}
and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= to_date(#{vdateStart},'yyyy-mm-dd')
and wft.SETTLE_DATE <= to_date(#{vdateEnd},'yyyy-mm-dd')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus}

select T.workStatus, T.settleDate, T.prodName, T.prodId, sum(T.tradeAmt) tradeAmt, T.portfolioId, T.portfolioName, T.ccy, T.allotAmt, T.hasChildren, T.childInfo, T.parentInfo, T.otherPortfolioId from (select '待处理' as workStatus, null as tradeId , /*交易编号*/ to_date(#{platDate},'yyyy-mm-dd') as settleDate, /**交易日sysdate modify by yanyan on 20191121 取当前平台日*/ fp.FINPROD_NAME as prodName,/*产品名称*/ fp.FINPROD_MARKET_ID as prodId,/*产品代码*/ pcp.AMOUNT as tradeAmt,/*交易金额*/ null as portfolioId,/*子组合代码*/ null as portfolioName,/*子组合名称*/ pcp.CCY as ccy,/*币种*/ null as allotAmt, /*分配金额*/ '02' hasChildren, CONCAT('待处理',nvl(fp.FINPROD_MARKET_ID,'null')) childInfo, 'root' parentInfo, pcp.PORTFOLIO_ID otherPortfolioId from PTL_CASH_POSITION_FLOW pcp /*组合现金流水*/ inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID
and pci.ACCT_TYPE=#{acctType}
inner join FIN_PRODUCT_ADD fpa /*标的类金融产品附属表*/ on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp /*标的类金融产品*/ on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp /*组合*/ on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} /*实际*/ and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null and fp.FINPROD_MARKET_ID not in( select wft.PORTFOLIO_ID as prodId from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID inner join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1 AND FINPROD_TYPE2=#{finprodType2}
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where 1=1
and wft.BUSI_TYPE=#{busiType}
and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= to_date(#{vdateStart},'yyyy-mm-dd')
and wft.SETTLE_DATE <= to_date(#{vdateEnd},'yyyy-mm-dd')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} group by wft.TOTLE_TRADE_ID,wft.SETTLE_DATE,fp.FINPROD_NAME, wft.PORTFOLIO_ID,wft.TRADE_AMt,wft.WORKFLOW_ID ) group by fp.FINPROD_NAME,fp.FINPROD_MARKET_ID, pcp.CCY,pcp.AMOUNT,pcp.seqNo ,pcp.PORTFOLIO_ID ) T group by T.prodName,T.prodId,T.CCY,T.otherPortfolioId,T.childInfo, T.workStatus, T.settleDate,T.hasChildren, T.parentInfo,T.allotAmt

select null as workStatus, null as tradeId , /*交易编号*/ null as settleDate, /*交易日*/ null as prodName,/*产品名称*/ null as prodId,/*产品代码*/ null as tradeAmt,/*交易金额*/ ptp.PORTFOLIO_ID as portfolioId,/*子组合代码*/ ptp.PORTFOLIO_NAME as portfolioName,/*子组合名称*/ null as ccy,/*币种*/ null as allotAmt, /*分配金额*/ null as seqNo, /*流水号*/ '01' hasChildren, CONCAT(CONCAT('待处理',nvl(fp.FINPROD_MARKET_ID,'null')),ptp.PORTFOLIO_ID) childInfo, CONCAT('待处理',nvl(fp.FINPROD_MARKET_ID,'null')) parentInfo from PTL_CASH_POSITION_FLOW pcp /*组合现金流水*/ inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID
and pci.ACCT_TYPE=#{acctType}
inner join FIN_PRODUCT_ADD fpa /*标的类金融产品附属表*/ on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp /*标的类金融产品*/ on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp /*组合*/ on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} /*实际*/ and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} ) and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null group by fp.FINPROD_NAME,fp.FINPROD_MARKET_ID,ptp.PORTFOLIO_ID, ptp.PORTFOLIO_NAME

select T1.seqNo from ( select fp.FINPROD_MARKET_ID as prodId,/*产品代码*/ pcp.seqNo /*流水号*/ from PTL_CASH_POSITION_FLOW pcp /*组合现金流水*/ inner join PTL_CAPACCT_INFO pci on pci.PORTFOLIO_ID=pcp.PORTFOLIO_ID and pci.CCY=pcp.CCY and pci.ACCT_NO=pcp.ACCT_ID
and pci.ACCT_TYPE=#{acctType}
inner join FIN_PRODUCT_ADD fpa /*标的类金融产品附属表*/ on pcp.PORTFOLIO_ID=fpa.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp /*标的类金融产品*/ on fp.FINPROD_ID=fpa.FINPROD_ID and fp.FINPROD_TYPE2 not in (#{dfinprodType2}) inner join PTL_PORTFOLIO ptp /*组合*/ on pcp.PORTFOLIO_ID=ptp.PARENT_PORTFOLIO_ID where pcp.HODING_TYPE=#{hodingType} /*实际*/ and pcp.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} ) and pcp.SPLIT_TYPE=#{splitType} or pcp.SPLIT_TYPE is null group by fp.FINPROD_MARKET_ID,pcp.seqNo )T1 WHERE T1.prodId=#{prodId}

select '流程中' as workStatus , wft.TOTLE_TRADE_ID as tradeId, wft.SETTLE_DATE as settleDate, fp.FINPROD_NAME as prodName, wft.PORTFOLIO_ID as prodId, wft.TRADE_AMT as tradeAmt, wta.PORTFOLIO_ID as portfolioId, ptp.PORTFOLIO_NAME as portfolioName, null as ccy, wpt.TRADE_AMT as allotAmt, null as seqNo, wft.WORKFLOW_ID as workflowId, '01' hasChildren, CONCAT(nvl(wft.PORTFOLIO_ID,'null'),'') childInfo, 'root' parentInfo from WFL_TRD_FIN_PRODUCT_DEAL_TOTAL wft left join WFL_PA_TRD_FIN_DEAL_TOTAl wdt on wdt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL wpt on wpt.TOTLE_TRADE_ID=wft.TOTLE_TRADE_ID left join WFL_TRD_PRODUCT_DEAL_ADD wta on wta.TRADE_ID=wpt.TRADE_ID left join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID=wta.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa on fpa.PORTFOLIO_ID=wft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp on fp.FINPROD_ID=fpa.FINPROD_ID where 1=1
and wft.BUSI_TYPE=#{busiType}
and wft.FINPROD_TYPE2=#{finprodType2} and wdt.PA_BUSS_TYPE=#{paBusiType} and wft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and wft.SETTLE_DATE >= to_date(#{vdateStart},'yyyy-mm-dd')
and wft.SETTLE_DATE <= to_date(#{vdateEnd},'yyyy-mm-dd')
and wft.IS_CANCEL !=#{isCancel} and wft.TRADE_STATUS=#{tardeStatus} union all select '有效' as workStatus, tft.TOTLE_TRADE_ID as tradeId,/*交易编号*/ tft.SETTLE_DATE as settleDate, /*交易日*/ fp.FINPROD_NAME as prodName,/*产品名称*/ fp.FINPROD_MARKET_ID as prodId,/*产品代码*/ tft.TRADE_AMT as tradeAmt,/*交易金额*/ tpa.PORTFOLIO_ID as portfolioId,/*子组合代码*/ ptp.PORTFOLIO_NAME as portfolioName,/*子组合名称*/ tft.ccy as ccy, tpd.TRADE_AMT as allotAmt, /*分配金额*/ null as seqNo, null as workflowId, '01' hasChildren, CONCAT(nvl(fp.FINPROD_MARKET_ID,'null'),'') childInfo, 'root' parentInfo from TRD_FIN_PRODUCT_DEAL_TOTAL tft /*金融产品汇总交易*/
LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL wdt /*金融产品交易汇总扩展*/ ON wdt.totle_trade_id=tft.totle_trade_id LEFT JOIN TRD_PRODUCT_DEAL tpd /*金融产品交易*/ ON tft.TOTLE_TRADE_ID=tpd.TOTLE_TRADE_ID left join TRD_PRODUCT_DEAL_ADD tpa /*金融产品交易附属表*/ on tpa.TRADE_ID=tpd.TRADE_ID left join PTL_PORTFOLIO ptp /*组合*/ on ptp.PORTFOLIO_ID=tpa.PORTFOLIO_ID inner join FIN_PRODUCT_ADD fpa /*标的类金融产品附属表*/ on fpa.PORTFOLIO_ID=tft.PORTFOLIO_ID inner join (select * from FIN_PRODUCT where 1=1
and FINPROD_MARKET_ID in (
#{item}
)
) fp /*标的类金融产品*/ on fp.FINPROD_ID=fpa.FINPROD_ID where 1=1
and tft.BUSI_TYPE=#{busiType}/*净值型TA交易*/
and tft.FINPROD_TYPE2=#{finprodType2} /*业务类型.理财产品*/ and wdt.PA_BUSS_TYPE =#{paBusiType} /*平安业务类型.产品交易资金分配*/ and tft.PORTFOLIO_ID in ( select ppa.PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY ppa where ppa.USER_ID=#{userId} )
and tft.TRADE_DATE >= to_date(#{vdateStart},'yyyy-mm-dd')
and tft.TRADE_DATE <= to_date(#{vdateEnd},'yyyy-mm-dd')
and tft.IS_CANCEL !=#{isCancel} /*是*/
